-- Joe&dave Operations Intelligence — D1 migration 0003
-- Supplier bills/payables, accounting period locks, and bank reconciliation primitives.
CREATE TABLE IF NOT EXISTS jd_supplier_bills (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),supplier_id TEXT NOT NULL REFERENCES jd_suppliers(id),bill_number TEXT NOT NULL,description TEXT NOT NULL,bill_date TEXT NOT NULL,due_date TEXT,subtotal_minor INTEGER NOT NULL CHECK(subtotal_minor>0),tax_minor INTEGER NOT NULL DEFAULT 0 CHECK(tax_minor>=0),total_minor INTEGER NOT NULL CHECK(total_minor>0),paid_minor INTEGER NOT NULL DEFAULT 0 CHECK(paid_minor>=0),currency_code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('draft','open','part_paid','paid','void')),reference TEXT,created_by TEXT REFERENCES jd_users(id),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(business_id,bill_number));
CREATE INDEX IF NOT EXISTS jd_supplier_bills_business_due_idx ON jd_supplier_bills(business_id,status,due_date);
CREATE TABLE IF NOT EXISTS jd_supplier_bill_payments (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),bill_id TEXT NOT NULL REFERENCES jd_supplier_bills(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),payment_method TEXT NOT NULL,paid_date TEXT NOT NULL,reference TEXT,created_by TEXT REFERENCES jd_users(id),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TRIGGER IF NOT EXISTS jd_supplier_payment_guard BEFORE INSERT ON jd_supplier_bill_payments WHEN (SELECT business_id FROM jd_supplier_bills WHERE id=NEW.bill_id) IS NULL OR (SELECT business_id FROM jd_supplier_bills WHERE id=NEW.bill_id)<>NEW.business_id OR NEW.amount_minor>(SELECT total_minor-paid_minor FROM jd_supplier_bills WHERE id=NEW.bill_id) BEGIN SELECT RAISE(ABORT,'supplier payment exceeds outstanding bill balance or scope is invalid'); END;
CREATE TRIGGER IF NOT EXISTS jd_supplier_payment_update AFTER INSERT ON jd_supplier_bill_payments BEGIN UPDATE jd_supplier_bills SET paid_minor=(SELECT COALESCE(SUM(amount_minor),0) FROM jd_supplier_bill_payments WHERE bill_id=NEW.bill_id),status=CASE WHEN (SELECT COALESCE(SUM(amount_minor),0) FROM jd_supplier_bill_payments WHERE bill_id=NEW.bill_id)>=total_minor THEN 'paid' WHEN (SELECT COALESCE(SUM(amount_minor),0) FROM jd_supplier_bill_payments WHERE bill_id=NEW.bill_id)>0 THEN 'part_paid' ELSE status END WHERE id=NEW.bill_id; END;
CREATE TABLE IF NOT EXISTS jd_accounting_periods (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),period_start TEXT NOT NULL,period_end TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),closed_by TEXT REFERENCES jd_users(id),closed_at TEXT,UNIQUE(business_id,period_start,period_end),CHECK(period_start<=period_end));
CREATE TRIGGER IF NOT EXISTS jd_journal_closed_period_guard BEFORE INSERT ON jd_journal_entries WHEN EXISTS(SELECT 1 FROM jd_accounting_periods p WHERE p.business_id=NEW.business_id AND p.status='closed' AND NEW.entry_date BETWEEN p.period_start AND p.period_end) BEGIN SELECT RAISE(ABORT,'accounting period is closed'); END;
CREATE TABLE IF NOT EXISTS jd_bank_accounts (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),name TEXT NOT NULL,account_mask TEXT,currency_code TEXT NOT NULL,opening_balance_minor INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS jd_bank_transactions (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),bank_account_id TEXT NOT NULL REFERENCES jd_bank_accounts(id),transaction_date TEXT NOT NULL,description TEXT NOT NULL,amount_minor INTEGER NOT NULL,reference TEXT,reconciled INTEGER NOT NULL DEFAULT 0 CHECK(reconciled IN (0,1)),matched_journal_entry_id TEXT REFERENCES jd_journal_entries(id),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS jd_bank_txn_reconcile_idx ON jd_bank_transactions(business_id,bank_account_id,reconciled,transaction_date);

CREATE TRIGGER IF NOT EXISTS jd_invoice_closed_period_guard BEFORE INSERT ON jd_invoices WHEN EXISTS(SELECT 1 FROM jd_accounting_periods p WHERE p.business_id=NEW.business_id AND p.status='closed' AND NEW.issue_date BETWEEN p.period_start AND p.period_end) BEGIN SELECT RAISE(ABORT,'accounting period is closed'); END;
CREATE TRIGGER IF NOT EXISTS jd_expense_closed_period_guard BEFORE INSERT ON jd_expenses WHEN EXISTS(SELECT 1 FROM jd_accounting_periods p WHERE p.business_id=NEW.business_id AND p.status='closed' AND NEW.expense_date BETWEEN p.period_start AND p.period_end) BEGIN SELECT RAISE(ABORT,'accounting period is closed'); END;
CREATE TRIGGER IF NOT EXISTS jd_supplier_bill_closed_period_guard BEFORE INSERT ON jd_supplier_bills WHEN EXISTS(SELECT 1 FROM jd_accounting_periods p WHERE p.business_id=NEW.business_id AND p.status='closed' AND NEW.bill_date BETWEEN p.period_start AND p.period_end) BEGIN SELECT RAISE(ABORT,'accounting period is closed'); END;
CREATE TRIGGER IF NOT EXISTS jd_receipt_closed_period_guard BEFORE INSERT ON jd_receipts WHEN EXISTS(SELECT 1 FROM jd_accounting_periods p WHERE p.business_id=NEW.business_id AND p.status='closed' AND date(NEW.received_at) BETWEEN p.period_start AND p.period_end) BEGIN SELECT RAISE(ABORT,'accounting period is closed'); END;
CREATE TRIGGER IF NOT EXISTS jd_supplier_payment_closed_period_guard BEFORE INSERT ON jd_supplier_bill_payments WHEN EXISTS(SELECT 1 FROM jd_accounting_periods p WHERE p.business_id=NEW.business_id AND p.status='closed' AND NEW.paid_date BETWEEN p.period_start AND p.period_end) BEGIN SELECT RAISE(ABORT,'accounting period is closed'); END;
